package com.mockarena.evaluation.infrastructure; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.math.*; import java.util.*;
@Component public class AssessmentCodingResultClient {private final RestClient client;private final String token;public AssessmentCodingResultClient(@Value("${assessment-service.base-url}")String base,@Value("${evaluation.workload-auth.assessment-snapshot-token:}")String token){client=RestClient.builder().baseUrl(base).build();this.token=token;}public void apply(UUID attemptId,Request request){try{client.post().uri("/internal/v1/attempts/{id}/coding-results",attemptId).header("X-MockArena-Workload-Token",token).body(request).retrieve().toBodilessEntity();}catch(RestClientException e){throw new RemoteDependencyException("ASSESSMENT_CALLBACK_UNAVAILABLE",e);}}public record Request(UUID evaluationJobId,int globalPosition,UUID questionId,UUID questionVersionId,String sourceFingerprint,String outcome,BigDecimal awardedScore,BigDecimal maxScore){}}
